import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"QQ Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/qq.md","filePath":"integrations/channels/qq.md","lastUpdated":1790952322000}'),n={name:"integrations/channels/qq.md"};function s(i,t,l,h,d,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="qq-channel-configuration" tabindex="-1">QQ Channel Configuration <a class="header-anchor" href="#qq-channel-configuration" aria-label="Permalink to &quot;QQ Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to QQ through QQ&#39;s official bot platform, for private chats, group chats, and thread (话题) conversations.</p><div class="warning custom-block"><p class="custom-block-title">Limits</p><ul><li>Each QQ account can create up to 5 bots.</li><li>Responses are delivered as complete blocks; output is not streamed token by token.</li></ul></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A QQ account, used to log in to the <a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot Open Platform</a>.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-create-a-qq-bot" tabindex="-1">1. Create a QQ bot <a class="header-anchor" href="#_1-create-a-qq-bot" aria-label="Permalink to &quot;1. Create a QQ bot&quot;">​</a></h3><p>In the QQ Bot Open Platform:</p><ol><li>Go to the <a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot Open Platform</a> and log in with your QQ account.</li><li>Click <strong>Create Bot</strong> (创建机器人) — no approval is required.</li><li>Copy the <strong>AppID</strong> and <strong>AppSecret</strong> displayed on the page. <strong>AppSecret</strong> is shown only once — save it securely.</li></ol><blockquote><p>Official resources: <a href="https://q.qq.com/" target="_blank" rel="noreferrer">QQ Bot Open Platform</a> · <a href="https://bot.q.qq.com/wiki/" target="_blank" rel="noreferrer">QQ Bot Documentation</a></p></blockquote><h3 id="_2-add-the-channel-in-memoh" tabindex="-1">2. Add the channel in Memoh <a class="header-anchor" href="#_2-add-the-channel-in-memoh" aria-label="Permalink to &quot;2. Add the channel in Memoh&quot;">​</a></h3><p>In Memoh:</p><ol><li>Open the bot&#39;s <strong>Platforms</strong> tab.</li><li>Click <strong>Add Channel</strong> and select <strong>QQ</strong>.</li><li>Paste the <strong>AppID</strong> and <strong>AppSecret</strong>.</li><li>Adjust the optional settings if needed: <strong>Markdown Support</strong> and <strong>Enable Input Hint</strong> are both enabled by default.</li><li>Click <strong>Save and Enable</strong>.</li></ol><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>AppID</strong></td><td>Yes</td><td>The bot&#39;s app ID, shown on the QQ Bot Open Platform when the bot is created.</td></tr><tr><td><strong>AppSecret</strong></td><td>Yes</td><td>The bot&#39;s app secret, shown only once at creation.</td></tr><tr><td><strong>Markdown Support</strong></td><td>No</td><td>Enable Markdown formatting (default: enabled).</td></tr><tr><td><strong>Enable Input Hint</strong></td><td>No</td><td>Show typing indicators while the bot generates a response (default: enabled).</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Send <code>/help</code> to the bot in a direct message, or @mention it in a group chat with <code>/help</code>. The bot replies with its command list, which confirms the channel is working.</p><h2 id="group-chats" tabindex="-1">Group chats <a class="header-anchor" href="#group-chats" aria-label="Permalink to &quot;Group chats&quot;">​</a></h2><p>The bot works in QQ group chats and thread (话题) conversations: @mention it in a group to trigger a reply.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>Disable or remove the channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate credentials, update <strong>AppID</strong> / <strong>AppSecret</strong> in the same panel and save.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h2><h3 id="appsecret-reset" tabindex="-1">I lost the AppSecret <a class="header-anchor" href="#appsecret-reset" aria-label="Permalink to &quot;I lost the AppSecret {#appsecret-reset}&quot;">​</a></h3><p><strong>AppSecret</strong> is shown only once, when the bot is created. Viewing it again on the QQ Bot Open Platform forces a reset; after the reset, update <strong>AppSecret</strong> in Memoh and save.</p>',24)])])}const g=e(n,[["render",s]]);export{u as __pageData,g as default};
